## Why This Is Asked
The Trie with prefix count mechanism addresses dynamic dictionary requirements in real-time applications like chat search, testing understanding of per-node frequency tracking, deletion correctness, and memory efficiency trade-offs.

## Key Concepts
- Trie with passCount and endCount for frequency tracking
- O(length) time complexity for all operations
- Memory management through node pruning
- Correct handling of duplicates and edge cases
- Amortized deletion: pruning happens during erase, no separate cleanup needed

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.pass = 0;
    this.end = 0;
  }
}

class Trie {
  constructor() {
    this.root = new TrieNode();
  }

  insert(word) {
    let node = this.root;
    node.pass++;
    for (const ch of word) {
      if (!node.children.has(ch)) {
        node.children.set(ch, new TrieNode());
      }
      node = node.children.get(ch);
      node.pass++;
    }
    node.end++;
  }

  exists(word) {
    const node = this._findNode(word);
    return node !== null && node.end > 0;
  }

  countPrefix(prefix) {
    const node = this._findNode(prefix);
    return node ? node.pass : 0;
  }

  erase(word) {
    if (!this.exists(word)) return false;

    let node = this.root;
    node.pass--;

    for (const ch of word) {
      const child = node.children.get(ch);
      child.pass--;
      if (child.pass === 0) {
        node.children.delete(ch);
        node = null;
        break;
      }
      node = child;
    }

    if (node) node.end--;
    return true;
  }

  _findNode(word) {
    let node = this.root;
    for (const ch of word) {
      if (!node.children.has(ch)) return null;
      node = node.children.get(ch);
    }
    return node;
  }
}

// Usage
const trie = new Trie();
trie.insert('apple');
trie.insert('apple');
trie.insert('app');
trie.exists('apple');        // true
trie.countPrefix('app');      // 3
trie.erase('apple');
trie.exists('apple');        // true (still one left)
trie.countPrefix('app');     // 2
trie.erase('apple');
trie.exists('apple');        // false
trie.countPrefix('app');      // 1
trie.erase('nonexistent');   // false (safe)
```

## Memory Management
Nodes are allocated only when needed and automatically pruned when `pass` reaches zero during erase, ensuring no memory leaks.

## Duplicate Handling
Since `end` tracks word frequency, duplicate inserts increment the counter; duplicate erases decrement it until the count reaches zero.

## Edge Cases
- Erase on non-existent word: returns false, no changes
- Erase on word with duplicate: only decrements count, preserves other instances
- Empty string handling: root node's counters track this case

## Why This Is Asked
This question tests mastery of three key concepts: Trie mutations (insert/delete), weighted dynamic programming for word break problems, and the ability to implement both iterative and recursive approaches. It also evaluates understanding of handling dynamic dictionary updates and edge cases such as when no valid decomposition exists.

## Key Concepts
- Trie with terminal weights for efficient prefix matching
- Dynamic insert/delete operations on Trie structure
- Weighted word-break DP with O(n × L) complexity where L = maxWordLen
- Both iterative bottom-up DP and memoized top-down DFS variants

## Code Example
```javascript
class TrieNode {
  constructor() {
    this.children = new Map();
    this.endWeight = 0;
    this.isEnd = false;
  }
}

class WeightedTrie {
  constructor() {
    this.root = new TrieNode();
    this.maxWordLen = 0;
  }

  insert(word, weight) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) {
        node.children.set(char, new TrieNode());
      }
      node = node.children.get(char);
    }
    node.isEnd = true;
    node.endWeight = weight;
    this.maxWordLen = Math.max(this.maxWordLen, word.length);
  }

  delete(word) {
    let node = this.root;
    for (const char of word) {
      if (!node.children.has(char)) return;
      node = node.children.get(char);
    }
    node.isEnd = false;
    node.endWeight = 0;
  }

  maxPartition(s) {
    const n = s.length;
    const dp = new Array(n + 1).fill(-1);
    dp[n] = 0;

    for (let i = n - 1; i >= 0; i--) {
      let node = this.root;
      for (let j = i; j < Math.min(n, i + this.maxWordLen); j++) {
        const char = s[j];
        if (!node.children.has(char)) break;
        node = node.children.get(char);
        if (node.isEnd && dp[j + 1] !== -1) {
          dp[i] = Math.max(dp[i], node.endWeight + dp[j + 1]);
        }
      }
    }
    return dp[0];
  }

  maxPartitionDFS(s, memo = {}) {
    if (s.length === 0) return 0;
    if (s in memo) return memo[s];

    let maxWeight = -1;
    let node = this.root;

    for (let i = 0; i < Math.min(s.length, this.maxWordLen); i++) {
      const char = s[i];
      if (!node.children.has(char)) break;
      node = node.children.get(char);

      if (node.isEnd) {
        const remaining = this.maxPartitionDFS(s.slice(i + 1), memo);
        if (remaining !== -1) {
          maxWeight = Math.max(maxWeight, node.endWeight + remaining);
        }
      }
    }
    memo[s] = maxWeight;
    return maxWeight;
  }
}
```

## Why This Is Asked
This problem validates DP mastery (two implementations) and handling of substring lookups with a dictionary. It stresses practical constraints and edge-case handling.

## Key Concepts
- Bottom-up DP, Memoization, Time: O(N * maxLen)
- Hash-map lookups for dictionary scores
- Edge cases: no decomposition, empty input, overlapping choices

## Code Example
```javascript
// Bottom-up
function maxScore(s, dict) {
  const maxLen = Math.max(...Object.keys(dict).map(k => k.length));
  const n = s.length;
  const NEG = -1e15;
  const dp = new Array(n + 1).fill(NEG);
  dp[0] = 0;
  for (let i = 1; i <= n; i++) {
    for (let len = 1; len <= Math.min(i, maxLen); len++) {
      const substr = s.slice(i - len, i);
      if (dict.hasOwnProperty(substr) && dp[i - len] !== NEG) {
        dp[i] = Math.max(dp[i], dp[i - len] + dict[substr]);
      }
    }
  }
  return dp[n] === NEG ? -1 : dp[n];
}

// Top-down
function maxScoreTopDown(s, dict) {
  const maxLen = Math.max(...Object.keys(dict).map(k => k.length));
  const memo = new Map();
  function solve(i) {
    if (i === s.length) return 0;
    if (memo.has(i)) return memo.get(i);
    let best = -Infinity;
    for (let len = 1; len <= Math.min(maxLen, s.length - i); len++) {
      const substr = s.substring(i, i + len);
      if (dict.hasOwnProperty(substr)) {
        const val = dict[substr] + solve(i + len);
        if (val > best) best = val;
      }
    }
    memo.set(i, best);
    return best;
  }
  const res = solve(0);
  return res === -Infinity ? -1 : res;
}
``` 

